`projects/{project}/locations/{location}/apis/{api}/versions/{version}/definitions/{definition}`

=item * C<< $msg->spec() >> / C<< $msg->spec($value) >>

Type: C<String>

Output only. The name of the spec from where the definition was parsed.
Format is
`projects/{project}/locations/{location}/apis/{api}/versions/{version}/specs/{spec}`

=item * C<< $msg->type() >> / C<< $msg->type($value) >>

Type: C<Enum> (L<Google::Cloud::Apihub::V1::Definition::Type>)

Output only. The type of the definition.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time at which the definition was created.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time at which the definition was last updated.

=item * C<< $msg->attributes() >> / C<< $msg->attributes($value) >>

Type: C<Message> (L<Google::Cloud::Apihub::V1::CommonFields::Definition::AttributesEntry>)

