`projects/{project}/locations/{location}/externalApi/{externalApi}`.

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

Required. Display name of the external API. Max length is 63 characters
(Unicode Code Points).

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

Optional. Description of the external API. Max length is 2000 characters
(Unicode Code Points).

=item * C<< $msg->endpoints() >> / C<< $msg->endpoints($value) >>

Type: C<String>

Optional. List of endpoints on which this API is accessible.

=item * C<< $msg->paths() >> / C<< $msg->paths($value) >>

Type: C<String>

Optional. List of paths served by this API.

=item * C<< $msg->documentation() >> / C<< $msg->documentation($value) >>

Type: C<Message> (L<Google::Cloud::Apihub::V1::CommonFields::Documentation>)

Optional. Documentation of the external API.

=item * C<< $msg->attributes() >> / C<< $msg->attributes($value) >>

Type: C<Message> (L<Google::Cloud::Apihub::V1::CommonFields::ExternalApi::AttributesEntry>)

Optional. The list of user defined attributes associated with the Version
resource. The key is the attribute name. It will be of the format:
`projects/{project}/locations/{location}/attributes/{attribute}`.
The value is the attribute values associated with the resource.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Creation timestamp.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Last update timestamp.

=back

