=head2 Google::Cloud::Apihub::V1::CommonFields::DiscoveredApiObservation

Respresents an API Observation observed in one of the sources.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. The name of the discovered API Observation.

Format:
`projects/{project}/locations/{location}/discoveredApiObservations/{discovered_api_observation}`

=item * C<< $msg->style() >> / C<< $msg->style($value) >>

Type: C<Enum> (L<Google::Cloud::Apihub::V1::DiscoveredApiObservation::Style>)

Optional. Style of ApiObservation

=item * C<< $msg->server_ips() >> / C<< $msg->server_ips($value) >>

Type: C<String>

Optional. The IP address (IPv4 or IPv6) of the origin server that the
request was sent to. This field can include port information. Examples:
`"192.168.1.1"`, `"10.0.0.1:80"`, `"FE80::0202:B3FF:FE1E:8329"`.

=item * C<< $msg->hostname() >> / C<< $msg->hostname($value) >>

Type: C<String>

Optional. The hostname of requests processed for this Observation.

=item * C<< $msg->last_event_detected_time() >> / C<< $msg->last_event_detected_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Optional. Last event detected time stamp

=item * C<< $msg->source_locations() >> / C<< $msg->source_locations($value) >>

Type: C<String>

Optional. The location of the observation source.

=item * C<< $msg->api_operation_count() >> / C<< $msg->api_operation_count($value) >>

Type: C<Int64>

Optional. The number of observed API Operations.

=item * C<< $msg->origin() >> / C<< $msg->origin($value) >>

Type: C<String>

Optional. For an observation pushed from a gcp resource, this would be the
gcp project id.

=item * C<< $msg->source_types() >> / C<< $msg->source_types($value) >>

Type: C<Enum> (L<Google::Cloud::Apihub::V1::DiscoveredApiObservation::SourceType>)

Optional. The type of the source from which the observation was collected.

=item * C<< $msg->known_operations_count() >> / C<< $msg->known_operations_count($value) >>

Type: C<Int64>

Output only. The number of known API Operations.

=item * C<< $msg->unknown_operations_count() >> / C<< $msg->unknown_operations_count($value) >>

Type: C<Int64>

Output only. The number of unknown API Operations.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Create time stamp of the observation in API Hub.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Update time stamp of the observation in API Hub.

=item * C<< $msg->source_metadata() >> / C<< $msg->source_metadata($value) >>

Type: C<Message> (L<Google::Cloud::Apihub::V1::CommonFields::SourceMetadata>)

Output only. The metadata of the source from which the observation was
collected.

=back

